# Code generated by Claude
"""
Run beaker-on-hotplate episodes (src/episode_runner.py): the controller in auto mode with the task policy, or in teleop mode.

    python experiments/beaker_hotplate_episode.py [--mode auto|teleop] [--arm-stage hold|request_operator|cheat] [--viewer] [--repeat N]
                                                  [--cross-check] [--record] [--out DIR]

--mode          auto (default): the task policy does staging, then its arm stage. teleop: no policy; the operator drives from the start
                with the keyboard (needs --viewer); time 0 is the handoff and the operator timeout (300 s) applies.
--arm-stage     the policy's arm stage after staging. hold (default): holds (expected outcome TIMEOUT after 60 s of auto time).
                request_operator: asks for operator control once, then holds (the controller switches to teleop; with a viewer the operator
                drives, F9 hands control back; headless nobody does and the operator timeout ends it). cheat: test only, the beaker is teleported
                onto the hotplate 2 s after the handoff (expected: SUCCESS).
--viewer        open the viewer (GLFW) and run in real time; needs a display. F9 toggles auto / teleop. Without it the run is headless (no window;
                the HANDOFF eagle frame is rendered through EGL, set MUJOCO_GL=egl on a machine without a display).
--repeat N      N episodes in a row on the SAME model (reset by mj_resetData); the logs are compared byte for byte.
--cross-check   also run one episode on a freshly loaded model (the first model is dropped first, to save memory) and compare it as well.
--record        record each episode (physics inputs + verification hashes) in DIR/run<k>/recording, for experiments/replay_run.py.
--out DIR       default data/beaker_hotplate_episodes/<auto_<arm stage> | teleop>[_viewer]; each episode goes to DIR/run<k>.
The HANDOFF eagle frame of the first episode is also copied to data/beaker_hotplate_eagle/episode_handoff.png.
"""

import argparse
import gc
import hashlib
import json
import os
import shutil
import sys
import time
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
if "--viewer" not in sys.argv and not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import glfw  # noqa: E402

from src.episode_runner import run_episode  # noqa: E402
from src.episode_test_sources import make_cheat_arm_stage  # noqa: E402
from src.task_policy import make_request_operator_stage  # noqa: E402
from src.glfw_viewer import make_glfw_viewer  # noqa: E402
from src.task_beaker_hotplate import load_task  # noqa: E402

ARM_STAGES = {"hold": None, "request_operator": lambda model, data: make_request_operator_stage(), "cheat": lambda model, data: make_cheat_arm_stage(model, data)}


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()[:16]


def show(summary, label):
    s = summary
    print(f"\n==================== {label}: {s['outcome']} ====================")
    if s.get("staging_error"):
        print("STAGING ERROR:", s["staging_error"])
    if s.get("phase_durations_s"):
        print("phase durations (sim s):", {k: (round(v, 2) if v is not None else None) for k, v in s["phase_durations_s"].items()})
    print(f"auto time after handoff {s['auto_time_after_handoff_s']:.1f} s, operator time {s['operator_time_s']:.1f} s"
          + (f", operator_assisted" if s["operator_assisted"] else "") + (f", {s['timeout_kind']} timeout" if s["timeout_kind"] else ""))
    for m in s["mode_switches"]:
        print(f"mode switch at t={m['time']:.2f} s: {m['from']} -> {m['to']} ({m['cause']}{': ' + m['reason'] if m['reason'] else ''}) [stage {m['stage']}]")
    if s["handoff_time"] is not None:
        print(f"HANDOFF at sim t = {s['handoff_time']:.2f} s; ended {s['time_after_handoff_to_end']:.2f} s later ({s['outcome']})")
    a = s.get("arrival_at_end_of_drive")
    if a:
        print(f"arrival at the end of DRIVE: {a['pos_err_mm']:.2f} mm, {a['yaw_err_deg']:+.3f} deg (tolerance 10 mm / 1 deg); re-approaches {s['drive_reapproaches']}")
    if s.get("base_pose_error_at_handoff"):
        e = s["base_pose_error_at_handoff"]
        print(f"base pose error at HANDOFF (after the corrections): {e['pos_err_mm']:.2f} mm, {e['yaw_err_deg']:+.3f} deg "
              f"(along the heading {e['along_mm']:+.1f} mm (+ = short of the pose, away from the bench), sideways {e['lateral_mm']:+.1f} mm)")
    print(f"turns: first {s['first_turn_deg']:.1f} deg; final in-place turn at the staging pose {s['final_in_place_turn_deg']:.2f} deg "
          f"(straight approach from the spawn implies {s['planned_final_turn_deg']:.2f} deg; the 5.7 cm swept clearance assumed a small one)")
    for c in s["pose_corrections"]:
        b, a = c["before"], c["after"]
        print(f"{c['phase']:17s}: {'needed' if c['needed'] else 'not needed'}; pose error {b['pos_mm']:.1f} mm / {b['yaw_deg']:+.2f} deg"
              + (f" -> {a['pos_mm']:.1f} mm / {a['yaw_deg']:+.2f} deg in {c['duration_s']:.1f} s ({c['status']})" if c["needed"] else "")
              + (f"; min clearance base {c['min_base_clearance_mm']:.0f} mm, arm {c['min_arm_clearance_mm']:.0f} mm" if c["min_arm_clearance_mm"] is not None else ""))
    for ph, d in s["base_drift"].items():
        print(f"base drift during {ph:8s}: net {d['net_pos_mm']:.3f} mm / {d['net_yaw_deg']:+.4f} deg, worst {d['max_pos_mm']:.3f} mm / {d['max_yaw_deg']:.4f} deg"
              + ("   (after HANDOFF)" if ph == "DONE" else ""))
    print(f"minimum base-to-bench clearance during DRIVE: {s['min_base_to_bench_clearance_during_drive_mm']:.1f} mm")
    if not s["contacts_by_phase"]:
        print("contacts during the episode: none")
    for ph, lst in s["contacts_by_phase"].items():
        for c in lst:
            print(f"contact in {ph}: {c['pair'][0]} - {c['pair'][1]}, sim t {c['first_s']:.2f}..{c['last_s']:.2f} s ({c['ticks']} ticks)")
    print("holds logged:", [(round(h["t_start"], 2), h["blocked_by"], h["waiting"], round(h["duration"], 2)) for h in s["holds"]] or "none")
    r = s["neck_framing_report"]
    if r:
        print(f"neck framing at HANDOFF: fits={r['fits']}, worst margin {100 * r['worst_margin']:.1f}%, aim error {r['aim_error_deg']:.2f} deg, contacts {r['contacts'] or 'none'}, "
              f"neck targets (deg) { {k: round(v * 57.29578, 1) for k, v in r['neck_targets'].items()} }")
    print("success check:", {k: ('ok' if v['ok'] else 'NOT') for k, v in (s["success_check"] or {}).items()})
    print(f"wall clock: {s['wall_seconds']:.1f} s")


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--mode", choices=["auto", "teleop"], default="auto",
                    help="auto: the task policy does the whole task; teleop: the operator (keyboard, needs --viewer) drives from the start, time 0 is the handoff")
    ap.add_argument("--arm-stage", choices=sorted(ARM_STAGES), default="hold",
                    help="the policy's arm stage after staging: hold (expect TIMEOUT), request_operator (asks for teleop once, then holds), cheat (test only: teleports the beaker, expect SUCCESS)")
    ap.add_argument("--viewer", action="store_true")
    ap.add_argument("--repeat", type=int, default=1)
    ap.add_argument("--cross-check", action="store_true")
    ap.add_argument("--out")
    ap.add_argument("--record", action="store_true", help="record each episode (physics inputs + verification hashes) in DIR/run<k>/recording for experiments/replay_run.py")
    args = ap.parse_args()
    out = Path(args.out) if args.out else PROJECT_ROOT / "data" / "beaker_hotplate_episodes" / (("teleop" if args.mode == "teleop" else "auto_" + args.arm_stage) + ("_viewer" if args.viewer else ""))
    runs = []

    def one(model, data, k, viewer=None, held=None):
        d = out / f"run{k}"
        summary = run_episode(ARM_STAGES[args.arm_stage], model, data, mode=args.mode, viewer=viewer, out_dir=d, handoff_frame=d / "handoff_eagle.png", held=held,
                              record_dir=d / "recording" if args.record else None)
        show(summary, f"{args.mode}{'/' + args.arm_stage if args.mode == 'auto' else ''} episode {k}" + (" (viewer)" if viewer else " (headless)"))
        runs.append(d)

    sim = load_task(cameras=True)
    model, data = sim.model, sim.data
    viewer = held = None
    if args.viewer:
        viewer = make_glfw_viewer(model, data, {"win": (1280, 960), "vsync": 0, "view_shadows": False, "shadowsize": None, "hud": True, "insets": True,
                                                "record": False, "snapshot_every": 0.0, "snapshot_dir": None, "bench_snap_dir": None,
                                                "bench_snap_frame": 15, "finish": False, "roundrobin": True,
                                                "record_fps": 62.5, "has_teleop": False, "has_auto": args.mode == "auto"})
        viewer["set_held"](viewer["key_down"])
        held = viewer["key_down"]
    for k in range(args.repeat):
        one(model, data, k + 1, viewer, held)
    if args.cross_check:
        if viewer is not None:
            print("(--cross-check is for headless runs; skipped with the viewer)")
        else:
            del sim, model, data
            gc.collect()
            sim = load_task(cameras=True)
            one(sim.model, sim.data, len(runs) + 1)
    if viewer is not None:
        viewer["close"]()
    first = runs[0] / "handoff_eagle.png"
    if first.exists():
        dest = PROJECT_ROOT / "data" / "beaker_hotplate_eagle" / ("episode_handoff.png" if not args.viewer else "episode_handoff_viewer.png")
        dest.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy(first, dest)
        print(f"\nHANDOFF eagle frame: {dest.relative_to(PROJECT_ROOT)}")
    if len(runs) > 1:
        print("\nreproducibility (SHA-256 of each episode's log; the summary JSON is compared without the wall-clock field):")
        ref_log, ref_sum = sha(runs[0] / "episode_log.csv"), None
        def strip(p):
            d = json.loads((p / "episode_summary.json").read_text()); d.pop("wall_seconds"); return json.dumps(d, sort_keys=True)
        ref_sum = strip(runs[0])
        for r in runs:
            print(f"  {r.name}: log {sha(r / 'episode_log.csv')}  summary {'identical' if strip(r) == ref_sum else 'DIFFERENT'}  frame {sha(r / 'handoff_eagle.png')}")
        print("  logs identical:", all(sha(r / "episode_log.csv") == ref_log for r in runs))


if __name__ == "__main__":
    main()
